head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > tooltipFormatterHeader]<br/>tooltipHeader=true 일때 Header 영역의 툴팁 내용을 동적으로 생성하기 위한 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "함수 설정 시, 함수의 반환값이 새로운 툴팁 텍스트로 적용됩니다.",
        "함수 설정 시, 사용자 함수에서 값을 반환하지 않으면 undefined 가 적용됩니다.",
        "함수 설정 시, 사용자 함수에서 ''(Empty String)을 반환하면 툴팁이 표시되지 않습니다.",
        "사용자 정의 함수에 colId 파라미터로 마우스가 오버된 Cell 의 ID 값이 전달됩니다.",
        "사용자 정의 함수에 label 파라미터로 마우스가 오버된 Cell 에 표시된 값이 전달됩니다.",
        "사용자 정의 함수의 반환값에 HTML 마크업을 포함할 수 있습니다.",
        "툴팁이 표시되지 않는 Cell 은 마우스를 오버해도 사용자 정의 함수가 실행되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 함수 실행 여부 추적용 (함수 미실행 검증)
    scwin.gVar = { executedColIds: [] };

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// Header 툴팁 사용자 정의 함수 (colId 별 분기)
// - 함수 실행 여부를 추적하여 '미표시 Cell 함수 미실행' 검증에 사용
scwin.target1_tooltipFormatterHeader = function (colId, label) {
    scwin.gVar.executedColIds.push(colId);

    if (colId === "col1") {
        // 반환값이 그대로 툴팁 텍스트로 적용 (파라미터명 라벨 + ' / ' 구분)
        return "colId: " + colId + " / label: " + label;
    } else if (colId === "col2") {
        // HTML 마크업 포함 반환 (파라미터명 라벨 + ' / ' 구분, label 에 마크업 적용)
        return "colId: " + colId + " / label: <b>" + label + "</b>";
    } else if (colId === "col3") {
        // ""(Empty String) 반환 -> 툴팁 미표시
        return "";
    } else if (colId === "col4") {
        // 값을 반환하지 않음 -> undefined 적용
        return;
    }
    return label;
};



// 표시된 Header 툴팁 정보를 return 영역에 출력하기 위한 클릭 리스너 (마우스오버 후 그 셀 클릭 시)
//  - 엔진은 셀 클릭의 기본/버블 처리 단계에서 hover 툴팁을 닫는다(display:none).
//    따라서 클릭의 캡처(capture) 단계 리스너로 잡아야 툴팁이 아직 살아있어 정상 출력된다.
//  - 리스너를 그리드 DOM 엘리먼트에 걸어 Header 클릭을 커버한다.
//  - 마우스오버만 해서는 출력되지 않으며, 클릭 시점에 현재 hover 로 표시된 툴팁 값이 캡처된다.
scwin.attachTooltipClick = function () {
    let gridEl = scwin.target1.getElement ? scwin.target1.getElement() : document.getElementById(scwin.target1.getID());
    if (!gridEl) { return; }
    if (scwin.tooltipClickFn && scwin.tooltipClickEl) {
        scwin.tooltipClickEl.removeEventListener("click", scwin.tooltipClickFn, true);
    }
    scwin.tooltipClickFn = function () { $c.gcm.getTooltipInfo(wf_body_bottom); };
    scwin.tooltipClickEl = gridEl;
    gridEl.addEventListener("click", scwin.tooltipClickFn, true);
};



// comp 생성
//  - 고정 전제 : tooltipHeader=true. con 에서 tooltipFormatterHeader 적용/미적용 선택.
//  - Header 폭을 좁게(width=70) 두고 긴 Header 값으로 잘림(truncation) 을 유도 -> tooltipHeader=true 일때 잘림 Header 만 툴팁 표시.
//  - 컬럼 구성 (Header 값 / formatter 분기)
//      col1 : 긴 Header(잘림) -> 반환값 colId+label 조합  (반환값이 툴팁 텍스트로 적용)
//      col2 : 긴 Header(잘림) -> HTML 마크업 반환
//      col3 : 긴 Header(잘림) -> ''(Empty String) 반환  -> 툴팁 미표시
//      col4 : 긴 Header(잘림) -> 미반환(return;)         -> undefined
//      col5 : 짧은 Header('처리', 미잘림) -> 잘림이 없어 툴팁 미표시 = 함수 미실행
scwin.comp_init = async function () {
    // 동적 생성용 네임스페이스 (페이지 scope 안전)
    let ns = 'xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms"';

    // 기존 target / dataList 정리
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 함수 실행 추적 초기화 (미표시 Header 마우스오버 시 함수 미실행 검증용)
    scwin.gVar.executedColIds = [];

    // 라벨 생성 (가장 먼저)
    $c.gcm.createLabel('label="[전제] tooltipHeader=true 고정. Header 폭이 좁아 긴 Header 값은 잘려 표시(짧은 처리 Header 는 모두 표시).\n[절차] 각 Header(th)에 마우스 오버 -> tooltipFormatterHeader 반환값이 툴팁으로 표시. con 에서 적용/미적용 선택 후 Target 재생성.\n[확인] col1=ID+값 조합, col2=HTML 마크업(굵게), col3=빈문자열(미표시), col4=미반환(undefined). 짧은 처리 Header 는 잘림이 없어 툴팁 미표시 -> 함수 미실행([함수 실행된 colId 확인] 버튼)."', '', 'label1');

    // dataList 생성 ($p.data.create 사용, body 컬럼 id 와 동일 컬럼명으로 바인딩)
    let dlt = '<w2:dataList ' + ns + ' baseNode="list" id="dlt_bind" repeatNode="map">';
    dlt += '<w2:columnInfo>';
    dlt += '<w2:column dataType="text" id="col1" name="col1"></w2:column>';
    dlt += '<w2:column dataType="text" id="col2" name="col2"></w2:column>';
    dlt += '<w2:column dataType="text" id="col3" name="col3"></w2:column>';
    dlt += '<w2:column dataType="text" id="col4" name="col4"></w2:column>';
    dlt += '<w2:column dataType="text" id="col5" name="col5"></w2:column>';
    dlt += '</w2:columnInfo>';
    dlt += '<w2:data use="true"></w2:data>';
    dlt += '</w2:dataList>';
    $p.data.create(dlt);
    let arrDC = $p.data.getAllDataCollection("object");
    scwin.dlt_bind = arrDC[arrDC.length - 1];
    scwin.dlt_bind.setJSON([
        { "col1": "010-1234-5678", "col2": "동의", "col3": "서울시 강남구", "col4": "1,250,000", "col5": "정상" },
        { "col1": "010-2222-3333", "col2": "미동의", "col3": "부산시 해운대구", "col4": "980,000", "col5": "보류" }
    ], false);

    // 조건 설정 - tooltipFormatterHeader 적용 여부
    let formatterApplied = con_tooltipFormatterHeader.getValue();
    let formatterAttr = (formatterApplied === 'true')
        ? 'tooltipFormatterHeader="scwin.target1_tooltipFormatterHeader" '
        : '';

    // target 생성 (Header 값을 의미있는 한글 라벨로 구성, 폭을 좁게 두어 긴 값 잘림 유발)
    let strTarget = '<w2:gridView ' + ns + ' tooltipHeader="true" ' + formatterAttr + 'dataList="data:dlt_bind" checkAllType="false" id="" style="width:520px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="70" inputType="text" id="col1" value="거래처 담당자 연락처"></w2:column>';
    strTarget += '<w2:column width="70" inputType="text" id="col2" value="마케팅 정보 수신 동의 여부"></w2:column>';
    strTarget += '<w2:column width="70" inputType="text" id="col3" value="배송지 상세 주소"></w2:column>';
    strTarget += '<w2:column width="70" inputType="text" id="col4" value="누적 결제 금액"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col5" value="처리"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="70" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="70" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="70" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="70" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col5" dataList="col5"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    let grp_comp = document.querySelector('.tc_group_basic');
    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 동적 생성(및 Target 재생성) 직후 툴팁 클릭 리스너 재부착
    scwin.attachTooltipClick();
}



// 현재 Header 툴팁 DOM 텍스트 확인
scwin.getHeaderTooltipText = function () {
    let tip = document.querySelector("#" + target1.id + "_tooltip");
    return tip ? tip.innerHTML : "(툴팁 DOM 없음)";
}

// 1) 함수 실행된 colId 목록 확인 (미표시 Header 는 함수 미실행)
scwin.btn_getExecutedColIds_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("함수 실행된 colId : " + JSON.stringify(scwin.gVar.executedColIds));
}

// 2) 현재 표시 중인 Header 툴팁 DOM 텍스트 확인
scwin.btn_getTooltipText_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("Header 툴팁 : " + scwin.getHeaderTooltipText());
}
